import psycopg, os; from dotenv import load_dotenv; load_dotenv(); conn = psycopg.connect(dbname=os.environ.get('DB_NAME'), user=os.environ.get('DB_USER'), password=os.environ.get('DB_PASSWORD'), row_factory=psycopg.rows.dict_row); cur = conn.cursor(); cur.execute("SELECT id FROM penghuni WHERE status = 'PENDING' LIMIT 1"); print(cur.fetchone()); cur.execute("SELECT id FROM kamar WHERE status = 'AVAILABLE' LIMIT 1"); print(cur.fetchone());